<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Database;use App\Core\Security;use App\Core\View;use App\Services\AuditService;use App\Services\ImportService;use App\Services\NotificationService;use App\Services\PermissionService;use App\Services\QueueService;use App\Services\ReportService;
final class ManagementController{
 private function guard(string $p):void{Auth::requireLogin();PermissionService::require(Auth::userId(),$p);}
 public function dashboard():void{$this->guard('dashboard.view');$stats=ReportService::dashboard();View::render('management/dashboard',compact('stats'));}
 public function rebuildQueue():void{$this->guard('prices.queue.manage');Security::verifyCsrf();$count=QueueService::rebuild();AuditService::log(Auth::userId(),'queue.rebuild',null,null,null,['count'=>$count]);Security::redirect('/dashboard');}
 public function categories():void{$this->guard('categories.view');$categories=Database::connection()->query('SELECT * FROM product_categories ORDER BY name')->fetchAll();View::render('management/categories',compact('categories'));}
 public function storeCategory():void{$this->guard('categories.manage');Security::verifyCsrf();$name=trim((string)($_POST['name']??''));$description=trim((string)($_POST['description']??''));if($name==='')exit('نام دسته الزامی است.');$s=Database::connection()->prepare('INSERT INTO product_categories(name,description) VALUES(:n,:d)');$s->execute(['n'=>$name,'d'=>$description?:null]);AuditService::log(Auth::userId(),'category.create','category',(string)Database::connection()->lastInsertId());Security::redirect('/admin/categories');}
 public function suppliers():void{$this->guard('suppliers.view');$suppliers=Database::connection()->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();View::render('management/suppliers',compact('suppliers'));}
 public function updateSupplier(int $id):void{$this->guard('suppliers.edit');Security::verifyCsrf();$s=Database::connection()->prepare('UPDATE suppliers SET code=:c,name=:n,phone=:p,email=:e,contact_name=:cn,notes=:no,updated_at=SYSDATETIME() WHERE id=:id');$s->execute(['c'=>trim((string)($_POST['code']??''))?:null,'n'=>trim((string)($_POST['name']??'')),'p'=>trim((string)($_POST['phone']??''))?:null,'e'=>trim((string)($_POST['email']??''))?:null,'cn'=>trim((string)($_POST['contact_name']??''))?:null,'no'=>trim((string)($_POST['notes']??''))?:null,'id'=>$id]);AuditService::log(Auth::userId(),'supplier.update','supplier',(string)$id);Security::redirect('/admin/suppliers');}
 public function archiveSupplier(int $id):void{$this->guard('suppliers.delete');Security::verifyCsrf();$s=Database::connection()->prepare('UPDATE suppliers SET is_active=0,updated_at=SYSDATETIME() WHERE id=:id');$s->execute(['id'=>$id]);AuditService::log(Auth::userId(),'supplier.archive','supplier',(string)$id);Security::redirect('/admin/suppliers');}
 public function storeSupplier():void{$this->guard('suppliers.create');Security::verifyCsrf();$s=Database::connection()->prepare('INSERT INTO suppliers(code,name,phone,email,contact_name,notes) VALUES(:c,:n,:p,:e,:cn,:no)');$s->execute(['c'=>trim((string)($_POST['code']??''))?:null,'n'=>trim((string)($_POST['name']??'')),'p'=>trim((string)($_POST['phone']??''))?:null,'e'=>trim((string)($_POST['email']??''))?:null,'cn'=>trim((string)($_POST['contact_name']??''))?:null,'no'=>trim((string)($_POST['notes']??''))?:null]);AuditService::log(Auth::userId(),'supplier.create','supplier',(string)Database::connection()->lastInsertId());Security::redirect('/admin/suppliers');}
 public function queue():void{$this->guard('prices.queue.manage');$pdo=Database::connection();$users=$pdo->query("SELECT id,name FROM users WHERE is_active=1 ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT TOP 500 q.*,p.product_code,p.product_name,u.name unit_name,usr.name assigned_name FROM price_queue q JOIN products p ON p.id=q.product_id JOIN units u ON u.id=p.unit_id LEFT JOIN users usr ON usr.id=q.assigned_to WHERE q.status IN('new','in_progress','needs_followup') ORDER BY q.score DESC,q.updated_at")->fetchAll();View::render('management/queue',compact('rows','users'));}
 public function updateQueue(int $id):void{$this->guard('prices.queue.manage');Security::verifyCsrf();$status=(string)($_POST['status']??'new');$allowed=['new','in_progress','completed','needs_followup'];if(!in_array($status,$allowed,true))exit('وضعیت نامعتبر است.');$assigned=(int)($_POST['assigned_to']??0);$note=trim((string)($_POST['result_note']??''));$s=Database::connection()->prepare("UPDATE price_queue SET status=:s,assigned_to=:u,result_note=:n,started_at=CASE WHEN :s='in_progress' AND started_at IS NULL THEN SYSDATETIME() ELSE started_at END,completed_at=CASE WHEN :s='completed' THEN SYSDATETIME() ELSE completed_at END,updated_at=SYSDATETIME() WHERE id=:id");$s->execute(['s'=>$status,'u'=>$assigned?:null,'n'=>$note?:null,'id'=>$id]);AuditService::log(Auth::userId(),'queue.update','queue',(string)$id,null,['status'=>$status,'assigned_to'=>$assigned,'note'=>$note]);Security::redirect('/admin/queue');}
 public function notifications():void{$this->guard('notifications.view');$rows=NotificationService::list(Auth::userId());View::render('management/notifications',compact('rows'));}
 public function readNotification(int $id):void{$this->guard('notifications.view');NotificationService::markRead($id,Auth::userId());Security::redirect('/notifications');}
 public function audit():void{$this->guard('audit.view');$rows=Database::connection()->query('SELECT TOP 300 a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC')->fetchAll();View::render('management/audit',compact('rows'));}
 public function reports():void{$this->guard('reports.view');$rows=ReportService::prices();View::render('management/reports',compact('rows'));}
 public function exportPrices():void{$this->guard('reports.export');$rows=ReportService::prices();header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment; filename=pricing-report.csv');echo "\xEF\xBB\xBF";$o=fopen('php://output','wb');fputcsv($o,['product_code','product_name','unit','latest_date','min_price','max_price','avg_price']);foreach($rows as $r)fputcsv($o,$r);fclose($o);exit;}
 public function settings():void{$this->guard('settings.view');$rows=Database::connection()->query('SELECT * FROM system_settings ORDER BY setting_key')->fetchAll();View::render('management/settings',compact('rows'));}
 public function saveSetting():void{$this->guard('settings.manage');Security::verifyCsrf();$k=trim((string)($_POST['setting_key']??''));$v=(string)($_POST['setting_value']??'');if($k==='')exit('کلید الزامی است.');$pdo=Database::connection();$s=$pdo->prepare('MERGE system_settings AS t USING (SELECT :k setting_key,:v setting_value,:u updated_by) s ON t.setting_key=s.setting_key WHEN MATCHED THEN UPDATE SET setting_value=s.setting_value,updated_by=s.updated_by,updated_at=SYSDATETIME() WHEN NOT MATCHED THEN INSERT(setting_key,setting_value,updated_by) VALUES(s.setting_key,s.setting_value,s.updated_by);');$s->execute(['k'=>$k,'v'=>$v,'u'=>Auth::userId()]);AuditService::log(Auth::userId(),'setting.update','setting',$k,null,$v);Security::redirect('/settings');}
 public function apiTokens():void{$this->guard('api.tokens.manage');$s=Database::connection()->prepare('SELECT id,name,last_used_at,expires_at,is_active,created_at FROM api_tokens WHERE user_id=:u ORDER BY created_at DESC');$s->execute(['u'=>Auth::userId()]);$tokens=$s->fetchAll();View::render('management/api-tokens',compact('tokens'));}
 public function revokeApiToken(int $id):void{$this->guard('api.tokens.manage');Security::verifyCsrf();$s=Database::connection()->prepare('UPDATE api_tokens SET is_active=0 WHERE id=:id AND user_id=:u');$s->execute(['id'=>$id,'u'=>Auth::userId()]);AuditService::log(Auth::userId(),'api_token.revoke','api_token',(string)$id);Security::redirect('/api-tokens');}
 public function createApiToken():void{$this->guard('api.tokens.manage');Security::verifyCsrf();$plain=bin2hex(random_bytes(32));$hash=hash('sha256',$plain);$name=trim((string)($_POST['name']??'API'));$s=Database::connection()->prepare("INSERT INTO api_tokens(user_id,name,token_hash,expires_at) VALUES(:u,:n,:h,:e)");$s->execute(['u'=>Auth::userId(),'n'=>$name,'h'=>$hash,'e'=>!empty($_POST['expires_at'])?$_POST['expires_at']:null]);AuditService::log(Auth::userId(),'api_token.create','api_token',(string)Database::connection()->lastInsertId());header('Content-Type:text/plain; charset=utf-8');echo "API token (only shown once): ".$plain;exit;}
 public function importForm():void{$this->guard('imports.view');View::render('management/import');}
 public function importProducts():void{$this->guard('imports.manage');Security::verifyCsrf();if(empty($_FILES['file']['tmp_name']))exit('فایل انتخاب نشده است.');$result=ImportService::productsCsv($_FILES['file']['tmp_name'],Auth::userId(),$_FILES['file']['name']);View::render('management/import-result',compact('result'));}
}